#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <set>
using namespace std;

int main(){
int classes=4,correct=2;
double epsilon=0.1,loss=0;
vector<double> probability={0.1,0.15,0.65,0.1};
for(int k=0;k<classes;k++){
    double target=(k==correct?1-epsilon:0)+epsilon/classes;
    loss-=target*log(probability[k]);
    cout<<"class "<<k<<" soft target "<<target<<"\n";
}
cout<<"smoothed cross entropy "<<loss<<"\n";
return 0;
}

