#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <string>
#include <set>
using namespace std;

int main(){
vector<double> positions={0,0.5,1};
vector<double> predictedReturn={0.01,-0.01,0.02};
double cost=0.002;
vector<double> value(3,-1e100),next(3,-1e100);
value[0]=0;
for(int t=0;t<int(predictedReturn.size());t++){
    fill(next.begin(),next.end(),-1e100);
    for(int old=0;old<3;old++)if(value[old]>-1e50)
        for(int action=0;action<3;action++){
            double reward=positions[action]*predictedReturn[t]
                         -cost*fabs(positions[action]-positions[old]);
            next[action]=max(next[action],value[old]+reward);
        }
    value=next;
}
cout<<"best three-step value "<<*max_element(value.begin(),value.end())<<"\n";
return 0;
}

